import sys, csv, numpy as np, importlib.util
from scipy.special import logsumexp
sys.argv=['x']
spec=importlib.util.spec_from_file_location('c','/scr/wurgaft/auto-psych/agent_trees/962b9e6d929c436d/repo/_runs/cell_1/experiment1/model_loop/iter_0/candidate_5/candidate.py')
c=importlib.util.module_from_spec(spec); spec.loader.exec_module(c)
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/962b9e6d929c436d/repo/_runs/cell_1/experiment1/model_loop/responses.csv')))
sets=[tuple(int(x) for x in r['number_set'].split(',')) for r in rows]
t=np.array([int(r['target'])-1 for r in rows]); y=np.array([int(r['rating']) for r in rows])
M=c.MEMBERSHIP; N=c.N_RULES; size=M.sum(1,keepdims=True)
def ll(alpha,lam,lapse,g,expo=1.0):
    E=np.log(alpha*M/size+(1-alpha)/100)
    prior=np.r_[np.full(N,np.log(lam/N)),np.full(M.shape[0]-N,np.log((1-lam)/1e4))]
    out=0
    cache={}
    for s in set(sets):
        lj=prior+expo*E[:,np.array(s)-1].sum(1); p=np.exp(lj-logsumexp(lj)); cache[s]=p@M
    p=np.array([cache[s][ti] for s,ti in zip(sets,t)]).clip(0,1)
    p=(1-lapse)*p+lapse*g
    return (y*np.log(p)+(1-y)*np.log(1-p)).sum()
best=None
for a in [0.5,0.7,0.9,0.97]:
  for lam in [0.3,0.5,0.8]:
    for lp in [0.1,0.2,0.3,0.4]:
      for e in [0.3,0.6,1.0]:
        v=ll(a,lam,lp,0.4,e); 
        if best is None or v>best[0]: best=(v,a,lam,lp,e)
print(best)
for e in [0.2,0.3,0.4,0.6,1.0]: print(e, max(ll(0.9,lam,lp,0.4,e) for lam in [0.3,0.5,0.8] for lp in [0.05,0.15,0.25,0.35]))
